{% extends "base.html" %}
{% block title %}{{ booking.title }}{% endblock %}
{% block announce %}{% if notice %}<p class="notice">{{ notice }}</p>{% endif %}{% endblock %}
{% block content %}
<h1 class="title">{{ booking.title }}</h1>
<dl class="booking-details">
  <dt>Room</dt>
  <dd>{{ booking.room.name }}, {{ booking.office_name }}</dd>
  <dt>When</dt>
  <dd>{{ booking.start_at|day }}, {{ booking.start_at|clock }}–{{ booking.end_at|clock }}</dd>
  <dt>Booked by</dt>
  <dd>{{ booking.organiser_name }}</dd>
  {% if booking.attendees_visible %}
  <dt>Attendees</dt>
  <dd>
    {% if booking.attendees %}
    <ul class="attendee-names">{% for name in booking.attendees %}<li>{{ name }}</li>{% endfor %}</ul>
    {% else %}None{% endif %}
  </dd>
  {% endif %}
</dl>
{% if confirming %}
<form class="confirm" method="post" action="/bookings/{{ booking.id }}/cancel">
  <p class="confirm-question">Cancel this booking? {{ booking.room.name }} becomes free for everyone.</p>
  <div class="form-actions">
    <button class="button button-secondary" type="submit">Cancel booking</button>
    <a class="button button-secondary" href="/bookings/{{ booking.id }}" autofocus>Keep booking</a>
  </div>
</form>
{% elif booking.can_cancel and not has_ended %}
<div class="form-actions">
  <a class="button button-secondary" href="/bookings/{{ booking.id }}/cancel">Cancel booking</a>
</div>
{% endif %}
<p class="lead back-link"><a href="/rooms">Back to rooms</a></p>
{% endblock %}
{% extends "base.html" %}
{% block title %}Book {{ room.name }}{% endblock %}
{% block announce %}{% if error %}<p class="error-message" role="alert">{{ error }}</p>{% endif %}{% endblock %}
{% block content %}
<h1 class="title">Book {{ room.name }}</h1>
<p class="meta">{{ office_name }} · {{ room.capacity }} {{ "person" if room.capacity == 1 else "people" }}{% if slot_text %} · {{ slot_text }}{% endif %}</p>
<form id="booking-form" class="booking-form" method="post" action="/bookings">
  {# Enter in a text box reloads the form (keeping what was typed) instead of booking. #}
  <button class="visually-hidden" type="submit" formaction="/bookings/new" formmethod="get" tabindex="-1" aria-hidden="true">Search</button>
  <input type="hidden" name="room" value="{{ room.id }}">
  <input type="hidden" name="date" value="{{ values.date }}">
  <input type="hidden" name="start" value="{{ values.start }}">
  <input type="hidden" name="length" value="{{ values.length }}">

  <div class="field">
    <label class="label" for="booking-title">Title</label>
    <input id="booking-title" class="input" name="title" type="text" value="{{ title }}" maxlength="100" autocomplete="off">
  </div>

  <fieldset class="attendees">
    <legend class="label">Attendees</legend>
    {% if attendees %}
    <ul class="chosen-list">
      {% for id, name in attendees %}
      <li class="chosen">
        <input type="hidden" name="attendee_id" value="{{ id }}">
        <span class="person-name">{{ name }}</span>
        <button class="button button-secondary" type="submit" name="remove" value="{{ id }}"
                formaction="/bookings/new" formmethod="get">Remove<span class="visually-hidden"> {{ name }}</span></button>
      </li>
      {% endfor %}
    </ul>
    {% else %}
    <p class="hint">No attendees yet. They are optional.</p>
    {% endif %}
    <label class="label" for="attendee-q">Add a person</label>
    <div class="search-row">
      <input id="attendee-q" class="input" name="q" type="search" value="{{ q }}"
             autocomplete="off" autocapitalize="words" spellcheck="false" aria-controls="people-results"
             hx-get="/bookings/new" hx-trigger="input changed delay:200ms, search"
             hx-include="closest form" hx-target="#people-results" hx-select="#people-results"
             hx-swap="outerHTML" hx-sync="this:replace">
      <button class="button button-secondary" type="submit" formaction="/bookings/new" formmethod="get">Search</button>
    </div>
    <div id="people-results" class="results" aria-live="polite">
      {% if q and not found %}
      <p class="hint">No one called “{{ q }}”.</p>
      {% elif found %}
      <ul class="people-list">
        {% for p in found %}
        <li>
          <button class="person-button" type="submit" name="add" value="{{ p.id }}"
                  formaction="/bookings/new" formmethod="get">
            <span class="person-name">Add {{ p.name }}</span>
            <span class="person-office">{{ p.home_office_name }}</span>
          </button>
        </li>
        {% endfor %}
      </ul>
      {% endif %}
    </div>
  </fieldset>

  <div class="form-actions">
    <button class="button button-primary" type="submit">Book</button>
    <a class="button button-secondary" href="/rooms?date={{ values.date|urlencode }}&start={{ values.start|urlencode }}&length={{ values.length|urlencode }}">Back to rooms</a>
  </div>
</form>
{% endblock %}
"""The only place that converts between UTC and UK time (AD-5).

Services work in aware UTC datetimes; the database holds UTC text
`YYYY-MM-DDTHH:MM:00Z`; the web layer turns UK dates and clock times into UTC with
`uk_to_utc` and back for display with the Jinja filters `clock` and `day`.
"""

from datetime import UTC, date, datetime, time, timedelta
from zoneinfo import ZoneInfo

UK = ZoneInfo("Europe/London")
UTC_FORMAT = "%Y-%m-%dT%H:%M:00Z"


def utc_now() -> datetime:
    """Now, in UTC. Tests replace this to fix the clock."""
    return datetime.now(UTC)


def to_text(moment: datetime) -> str:
    return moment.astimezone(UTC).strftime(UTC_FORMAT)


def from_text(text: str) -> datetime:
    return datetime.strptime(text, UTC_FORMAT).replace(tzinfo=UTC)


def uk_now() -> datetime:
    return utc_now().astimezone(UK)


def parse_date(text: str) -> date | None:
    try:
        return date.fromisoformat(text.strip())
    except ValueError:
        return None


def parse_clock(text: str) -> time | None:
    text = text.strip()
    if len(text) != 5 or text[2] != ":":
        return None
    try:
        return time.fromisoformat(text)
    except ValueError:
        return None


def uk_to_utc(day: date, clock: time) -> datetime | None:
    """The UTC moment of a UK date and clock time, or None when the clocks skip it.

    In the autumn hour that happens twice, the first (summer time) one is meant.
    """
    local = datetime.combine(day, clock).replace(tzinfo=UK, fold=0)
    moment = local.astimezone(UTC)
    if moment.astimezone(UK).replace(tzinfo=None) != local.replace(tzinfo=None):
        return None
    return moment


def uk_midnight(day: date) -> datetime:
    """The UTC moment a UK day starts. UK clocks change at 01:00 or 02:00, so midnight
    always exists and happens once."""
    return datetime.combine(day, time()).replace(tzinfo=UK).astimezone(UTC)


def week_start(day: date) -> date:
    """The Monday of `day`'s week."""
    return day - timedelta(days=day.weekday())


def next_quarter_hour(moment: datetime) -> datetime:
    """`moment` rounded up to a quarter hour (unchanged when it is on one)."""
    moment = moment.replace(second=0, microsecond=0) + (
        timedelta(minutes=1) if moment.second or moment.microsecond else timedelta()
    )
    return moment + timedelta(minutes=-moment.minute % 15)


def clock(moment: datetime) -> str:
    """`14:00`, in UK time."""
    return moment.astimezone(UK).strftime("%H:%M")


def day(moment: datetime) -> str:
    """`Tue 17 Nov`, in UK time."""
    local = moment.astimezone(UK)
    return f"{local:%a} {local.day} {local:%b}"


def length_label(minutes: int) -> str:
    """`15 min`, `1 h`, `1 h 45 min`."""
    hours, rest = divmod(minutes, 60)
    parts = ([f"{hours} h"] if hours else []) + ([f"{rest} min"] if rest else [])
    return " ".join(parts)
